static void destroy(struct TreeNode *node) {
  if (!node) return;
  destroy(node->left);
  destroy(node->right);
  free(node);
}

static struct TreeNode *clone(struct TreeNode *node) {
  if (!node) return NULL;
  struct TreeNode *n = (struct TreeNode *)malloc(sizeof(struct TreeNode));
  n->val = node->val;
  n->left = clone(node->left);
  n->right = clone(node->right);
  return n;
}

static struct TreeNode **gen(int start, int end, int *count) {
  struct TreeNode **res = (struct TreeNode **)malloc(sizeof(struct TreeNode *) * 2000);
  *count = 0;
  if (start > end) {
    res[(*count)++] = NULL;
    return res;
  }
  for (int i = start; i <= end; i++) {
    int lc, rc;
    struct TreeNode **lefts = gen(start, i - 1, &lc);
    struct TreeNode **rights = gen(i + 1, end, &rc);
    for (int l = 0; l < lc; l++) {
      for (int r = 0; r < rc; r++) {
        struct TreeNode *root = (struct TreeNode *)malloc(sizeof(struct TreeNode));
        root->val = i;
        root->left = clone(lefts[l]);
        root->right = clone(rights[r]);
        res[(*count)++] = root;
      }
    }
    for (int l = 0; l < lc; l++) destroy(lefts[l]);
    for (int r = 0; r < rc; r++) destroy(rights[r]);
    free(lefts);
    free(rights);
  }
  return res;
}

struct TreeNode **generateTrees(int n, int *returnSize) {
  if (n == 0) {
    *returnSize = 0;
    return NULL;
  }
  return gen(1, n, returnSize);
}

class Solution {
  static void destroy(TreeNode *node) {
    if (!node) return;
    destroy(node->left);
    destroy(node->right);
    delete node;
  }

  static TreeNode *clone(TreeNode *node) {
    if (!node) return nullptr;
    TreeNode *n = new TreeNode(node->val);
    n->left = clone(node->left);
    n->right = clone(node->right);
    return n;
  }

  vector<TreeNode *> gen(int start, int end) {
    vector<TreeNode *> res;
    if (start > end) {
      res.push_back(nullptr);
      return res;
    }
    for (int i = start; i <= end; i++) {
      vector<TreeNode *> lefts = gen(start, i - 1);
      vector<TreeNode *> rights = gen(i + 1, end);
      for (TreeNode *l : lefts) {
        for (TreeNode *r : rights) {
          TreeNode *root = new TreeNode(i);
          root->left = clone(l);
          root->right = clone(r);
          res.push_back(root);
        }
      }
      for (TreeNode *l : lefts) destroy(l);
      for (TreeNode *r : rights) destroy(r);
    }
    return res;
  }

public:
  vector<TreeNode *> generateTrees(int n) {
    if (n == 0) return {};
    return gen(1, n);
  }

  static void freeTrees(vector<TreeNode *> &trees) {
    for (TreeNode *t : trees) destroy(t);
  }
};

func generateTrees(n int) []*TreeNode {
	if n == 0 {
		return nil
	}
	var gen func(start, end int) []*TreeNode
	gen = func(start, end int) []*TreeNode {
		if start > end {
			return []*TreeNode{nil}
		}
		var res []*TreeNode
		for i := start; i <= end; i++ {
			lefts := gen(start, i-1)
			rights := gen(i+1, end)
			for _, l := range lefts {
				for _, r := range rights {
					res = append(res, &TreeNode{Val: i, Left: l, Right: r})
				}
			}
		}
		return res
	}
	return gen(1, n)
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }

  TreeNode(int x, TreeNode left, TreeNode right) {
    val = x;
    this.left = left;
    this.right = right;
  }
}

class Solution {
  private List<TreeNode> gen(int start, int end) {
    List<TreeNode> res = new ArrayList<>();
    if (start > end) {
      res.add(null);
      return res;
    }
    for (int i = start; i <= end; i++) {
      List<TreeNode> lefts = gen(start, i - 1);
      List<TreeNode> rights = gen(i + 1, end);
      for (TreeNode l : lefts) {
        for (TreeNode r : rights) {
          res.add(new TreeNode(i, l, r));
        }
      }
    }
    return res;
  }

  public List<TreeNode> generateTrees(int n) {
    if (n == 0) return new ArrayList<>();
    return gen(1, n);
  }
}

class Solution:
    def generateTrees(self, n: int) -> List[Optional[TreeNode]]:
        if n == 0:
            return []

        def gen(start: int, end: int) -> List[Optional[TreeNode]]:
            if start > end:
                return [None]
            res = []
            for i in range(start, end + 1):
                lefts = gen(start, i - 1)
                rights = gen(i + 1, end)
                for l in lefts:
                    for r in rights:
                        res.append(TreeNode(i, l, r))
            return res

        return gen(1, n)

impl Solution {
  pub fn generate_trees(n: i32) -> Vec<Option<Box<TreeNode>>> {
    if n == 0 {
      return vec![];
    }
    fn gen(start: i32, end: i32) -> Vec<Option<Box<TreeNode>>> {
      if start > end {
        return vec![None];
      }
      let mut res = vec![];
      for i in start..=end {
        let lefts = gen(start, i - 1);
        let rights = gen(i + 1, end);
        for l in &lefts {
          for r in &rights {
            res.push(Some(Box::new(TreeNode {
              val: i,
              left: l.clone(),
              right: r.clone(),
            })));
          }
        }
      }
      res
    }
    gen(1, n)
  }
}

const generateTrees = (n: number): Array<TreeNode | null> => {
  if (n === 0) return [];

  const gen = (start: number, end: number): Array<TreeNode | null> => {
    if (start > end) return [null];
    const res: Array<TreeNode | null> = [];
    for (let i = start; i <= end; i++) {
      const lefts = gen(start, i - 1);
      const rights = gen(i + 1, end);
      for (const l of lefts) {
        for (const r of rights) {
          res.push(new TreeNode(i, l, r));
        }
      }
    }
    return res;
  };

  return gen(1, n);
};
